Color riskColor(String level) => switch(level) { 'CRITICAL' => red, 'HIGH' => orange, 'MEDIUM' => yellow, _ => green };
String riskLevel(double score) => score >= 75 ? 'CRITICAL' : score >= 50 ? 'HIGH' : score >= 25 ? 'MEDIUM' : 'LOW';
String fmt(dynamic v) { if (v == null) return 'ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط£آ¢أ¢â€ڑآ¬أ¢â‚¬إ’'; final d = DateTime.tryParse(v.toString())?.toLocal(); return d == null ? v.toString() : '${d.day.toString().padLeft(2,'0')} ${_months[d.month-1]} ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}'; }
const _months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

class Api {
  static String base = const String.fromEnvironment('API_BASE', defaultValue: 'http://10.0.2.2:8000');
  static Future<void> saveBase(String value) async { var v=value.trim().replaceAll(RegExp(r'/+$'), ''); if (!v.startsWith('http://') && !v.startsWith('https://')) v='http://$v'; base=v; final sp=await SharedPreferences.getInstance(); await sp.setString('api_base', base); }
  static String friendlyError(Object e) { final m=e.toString(); if (m.contains('SocketException') || m.contains('Failed host lookup') || m.contains('Connection refused') || m.contains('TimeoutException')) return 'Cannot reach the server. Check that the API is running and the phone can reach the computer. On a real phone, set the computer LAN IP in Server settings.'; return m.replaceFirst('Exception: ', ''); }
  static String? token;
  static String get role {
    try {
      if (token == null) return '';
      final parts = token!.split('.');
      if (parts.length < 2) return '';
      final normalized = base64Url.normalize(parts[1]);
      final payload = jsonDecode(utf8.decode(base64Url.decode(normalized)));
      return (payload['role'] ?? '').toString().toLowerCase();
    } catch (_) { return ''; }
  }
  static bool get isAdmin => role == 'admin';
  static Future<bool> login(String u, String p) async { final r=await http.post(Uri.parse('$base/auth/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':u,'password':p})).timeout(const Duration(seconds:12)); if(r.statusCode!=200)return false; token=jsonDecode(r.body)['access_token']; final sp=await SharedPreferences.getInstance(); await sp.setString('token',token!); return true; }
  static Future<void> restore() async {
    final sp=await SharedPreferences.getInstance();
    base=sp.getString('api_base') ?? base;
    token=sp.getString('token');
    // Do not reopen the console with an expired persisted JWT; that causes a permanent retry screen.
    if (token != null) {
      try {
        final parts=token!.split('.');
        final payload=jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(parts[1]))));
        final exp=payload['exp'];
        if (exp is num && DateTime.now().millisecondsSinceEpoch ~/ 1000 >= exp) {
          token=null; await sp.remove('token');
        }
      } catch (_) { token=null; await sp.remove('token'); }
    }
  }
  static Future<bool> register(String u,String p,String d,String j) async { final r=await http.post(Uri.parse('$base/auth/register'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':u,'password':p,'department':d,'job_role':j})).timeout(const Duration(seconds:12)); if(r.statusCode!=200)return false; token=jsonDecode(r.body)['access_token']; final sp=await SharedPreferences.getInstance(); await sp.setString('token',token!); return true; }
  static Future<String> requestPasswordReset(String u) async { final r=await http.post(Uri.parse('$base/api/v1/password-reset-requests'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':u})).timeout(const Duration(seconds:12)); if(r.statusCode>=400) throw Exception(_err(r)); return jsonDecode(r.body)['message']?.toString() ?? 'Request sent to administrator.'; }
  static Future<String> passwordResetStatus(String u) async { final r=await http.get(Uri.parse('$base/api/v1/password-reset-requests/status?username=${Uri.encodeQueryComponent(u)}')).timeout(const Duration(seconds:12)); if(r.statusCode>=400) throw Exception(_err(r)); return jsonDecode(r.body)['status']?.toString() ?? 'NONE'; }
  static Future<String> completePasswordReset(String u,String temporary,String next,String confirm) async { final r=await http.post(Uri.parse('$base/api/v1/password-reset-requests/complete'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':u,'temporary_password':temporary,'new_password':next,'confirm_password':confirm})).timeout(const Duration(seconds:12)); if(r.statusCode>=400) throw Exception(_err(r)); return jsonDecode(r.body)['message']?.toString() ?? 'Password changed successfully.'; }
  static Future<void> logout() async { token=null; final sp=await SharedPreferences.getInstance(); await sp.remove('token'); }
  static Future<dynamic> get(String path) async { final r=await http.get(Uri.parse('$base$path'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12)); if(r.statusCode==401)throw Exception('SESSION_EXPIRED'); if(r.statusCode>=400)throw Exception('Request failed'); return jsonDecode(r.body); }
  static Future<dynamic> getV1(String path) async { final r=await http.get(Uri.parse('$base/api/v1$path'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12)); if(r.statusCode==401)throw Exception('SESSION_EXPIRED'); if(r.statusCode>=400)throw Exception(_err(r)); return jsonDecode(r.body); }
  static Future<dynamic> postV1(String path,Map body) async { final r=await http.post(Uri.parse('$base/api/v1$path'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode(body)).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); return jsonDecode(r.body); }
  static Future<dynamic> createUser(Map body) async { final r=await http.post(Uri.parse('$base/users'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode(body)).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); return jsonDecode(r.body); }
  static Future<dynamic> updateUser(int id,Map body) async { final r=await http.put(Uri.parse('$base/users/$id'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode(body)).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); return jsonDecode(r.body); }
  static Future<dynamic> listAccounts() async => getV1('/accounts');
  static Future<dynamic> updateAccount(int id,Map body) async => patchV1('/accounts/$id',body);
  static Future<dynamic> patchV1(String path,Map body) async { final r=await http.patch(Uri.parse('$base/api/v1$path'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode(body)).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); return jsonDecode(r.body); }
  static Future<void> deleteUser(int id) async { final r=await http.delete(Uri.parse('$base/users/$id'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); }
  static String _err(http.Response r){try{return jsonDecode(r.body)['detail']?.toString()??'Request failed';}catch(_){return 'Request failed';}}
  static Future<dynamic> responseActions(int id) async => getV1('/alerts/$id/response-actions');
  static Future<dynamic> runResponseAction(int id,String action) async => postV1('/alerts/$id/response-actions/$action',{});
  static Future<void> updateAlert(int id,String status) async { final r=await http.put(Uri.parse('$base/alerts/$id'),headers:{'Authorization':'Bearer $token','Content-Type':'application/json'},body:jsonEncode({'status':status})).timeout(const Duration(seconds:12)); if(r.statusCode>=400)throw Exception(_err(r)); }
}

