          ListTile(contentPadding: EdgeInsets.zero, leading: Icon(r['status']=='PENDING'?Icons.notifications_active_outlined:Icons.check_circle_outline,color:r['status']=='PENDING'?orange:green), title: Text(r['username'].toString()), subtitle: Text('${r['email'] ?? 'No registered email'}\n${r['status']} ط·آ·ط¢آ¢ط·آ¢ط¢آ· ${fmt(r['created_at'])}')),
          if (r['status']=='PENDING') Wrap(spacing: 8, children: [FilledButton(onPressed: () async {
            final temp = TextEditingController();
            final picked = await showDialog<String>(context: ctx, builder: (dctx) => AlertDialog(title: const Text('Approve reset'), content: TextField(controller: temp, obscureText: true, decoration: const InputDecoration(labelText: 'Temporary password (10+ characters)')), actions: [TextButton(onPressed: ()=>Navigator.pop(dctx), child: const Text('Cancel')), FilledButton(onPressed: ()=>temp.text.length>=10?Navigator.pop(dctx,temp.text):ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Use at least 10 characters'))), child: const Text('Approve'))]));
            if (picked == null) return;
            try { await Api.postV1('/password-reset-requests/${r['id']}/review', {'action':'approve','new_password':picked}); await reloadDialog(setDialog); if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Approved. Temporary password emailed to the user.'))); }
            catch(e) { if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); }
          }, child: const Text('Approve')), OutlinedButton(onPressed: () async {
            final yes = await showDialog<bool>(context: ctx, builder: (dctx)=>AlertDialog(title: const Text('Reject request?'), content: Text('Reject password reset for ${r['username']}?'), actions:[TextButton(onPressed:()=>Navigator.pop(dctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(dctx,true),child:const Text('Reject'))]));
