Future<void> _deleteUser(BuildContext context,int id) async {final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('Delete user?'),content:Text('This will remove the user and related activity/alerts.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:Text('Delete'))]));if(ok==true){try{await Api.deleteUser(id);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('User deleted')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}}

class UserDetailPage extends StatelessWidget{final Map user;final List alerts,activities;UserDetailPage({super.key,required this.user,required this.alerts,required this.activities});@override Widget build(BuildContext c){final open=alerts.where((a)=>a['status']=='OPEN'||a['status']=='INVESTIGATING').toList();final score=open.isEmpty?0.0:open.map((a)=>(a['risk_score'] as num).toDouble()).reduce((a,b)=>a>b?a:b);final lv=riskLevel(score);return Scaffold(appBar:AppBar(title:Text(user['username'])),body:ListView(padding:EdgeInsets.all(16),children:[_Panel(title:'Risk posture',subtitle:'Current open-alert score',child:Column(children:[Text(score.toStringAsFixed(0),style:TextStyle(fontSize:48,fontWeight:FontWeight.w800,color:riskColor(lv))),Text(lv,style:TextStyle(color:riskColor(lv),fontWeight:FontWeight.w800)),SizedBox(height:14),_kv('Department',user['department']),_kv('Role',user['job_role']),_kv('Status',user['status']),_kv('Alerts',alerts.length.toString()),_kv('Recent activity',activities.length.toString())])),SizedBox(height:12),_Panel(title:'Previous alerts',subtitle:'Investigation history',child:Column(children:alerts.take(7).map((a)=>_AlertTile(a,[user])).toList())),SizedBox(height:12),_Panel(title:'Recent activity',subtitle:'Latest user events',child:Column(children:activities.take(8).map((a)=>_ActivityTile(a,[user])).toList()))]));}}

class ActivityPage extends StatefulWidget{ActivityPage({super.key});@override State<ActivityPage>createState()=>_ActivityPageState();}
class _ActivityPageState extends State<ActivityPage>{late Future<_Data>f;String type='';@override void initState(){super.initState();f=load();}Future<_Data>load()async{final a=await Api.get('/activities?limit=200'),u=await Api.get('/users');return _Data({},[],u,a);} @override Widget build(BuildContext c)=>FutureBuilder<_Data>(future:f,builder:(c,x){if(!x.hasData)return x.hasError?_retry(()=>setState(()=>f=load())):Center(child:CircularProgressIndicator());final d=x.data!,rows=d.activities.where((a)=>type.isEmpty||a['event_type']==type).toList();return ListView(padding:EdgeInsets.all(16),children:[_dropdown('Event type',type,['','LOGIN','FILE_ACCESS','FILE_DOWNLOAD','FILE_UPLOAD','FILE_DELETE','USB_CONNECT','USB_TRANSFER','EMAIL_SENT'],(v)=>setState(()=>type=v!)),SizedBox(height:12),_Panel(title:'Activity stream',subtitle:'${rows.length} recent events',child:Column(children:rows.take(100).map((a)=>_ActivityTile(a,d.users)).toList()))]);});
Widget _dropdown(String label,String val,List<String>items,ValueChanged<String?>on)=>Container(padding:EdgeInsets.symmetric(horizontal:10),decoration:BoxDecoration(color:panel2,border:Border.all(color:cyan.withOpacity(.28)),borderRadius:BorderRadius.circular(11),boxShadow:[BoxShadow(color:Colors.black.withOpacity(.16),blurRadius:12,offset:Offset(0,5))]),child:DropdownButtonHideUnderline(child:DropdownButton<String>(value:val,dropdownColor:panel,items:items.map((x)=>DropdownMenuItem(value:x,child:Text(x.isEmpty?'All $label':x.replaceAll('_',' '),style:TextStyle(fontSize:10)))).toList(),onChanged:on)));
}
